/*
 * A192521  Monotonic ordering of set S generated by these rules: if x and y
 *          are in S then floor((x+1)(y+1)/2) is in S, and 2 is in S.
 * https://oeis.org/A192521
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 8, u16 n <= 57, u32 n <= 57, u64 n <= 57, u128 n <= 57,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: a(n) is the n‑th element of the set S generated by
 *   a(1) = 2
 *   if x,y∈S then floor((x+1)(y+1)/2)∈S
 * The values are returned in increasing order, with duplicates removed.
 * The algorithm keeps a min‑heap of candidate pairs (i,j) that produce
 * new values and a wait list for pairs whose second index is not yet
 * known.  It runs in O(n) time with a very small constant factor. */

#include <stddef.h>
#include <stdlib.h>
#include <stdbool.h>

/* Node used in the min‑heap */
typedef struct {
    seq_t val;   /* value of floor((x_i+1)(x_j+1)/2) */
    idx_t i;     /* first index of the pair */
    idx_t j;     /* second index of the pair */
} HeapNode;

/* Array of first indices waiting for a particular second index */
typedef struct {
    idx_t *d;    /* dynamic array of indices */
    size_t len;  /* filled length */
    size_t cap;  /* allocated capacity */
} IdxArr;

/* Global state, initialized lazily on the first call to a() */
static struct {
    seq_t  *seq;          /* generated sequence (0‑based) */
    size_t  seq_len;      /* number of generated elements */
    size_t  seq_cap;      /* allocated capacity of seq[] */

    IdxArr *wait;        /* wait[j] holds indices i with that j */
    size_t  wait_cap;    /* allocated size of the wait array */

    HeapNode *heap;      /* binary min‑heap of candidate pairs */
    size_t    heap_len;  /* number of elements in the heap */
    size_t    heap_cap;  /* allocated capacity of the heap */

    seq_t last_val;      /* last distinct value inserted */
} st;

/* Ensure that st.seq has capacity at least need */
static void st_ensure_seq(size_t need)
{
    if (need <= st.seq_cap) return;
    size_t newcap = st.seq_cap ? st.seq_cap * 2 : 4;
    while (newcap < need) newcap <<= 1;
    st.seq = (seq_t*)realloc(st.seq, newcap * sizeof(seq_t));
    st.seq_cap = newcap;
}

/* Ensure that st.heap has capacity at least need */
static void st_ensure_heap(size_t need)
{
    if (need <= st.heap_cap) return;
    size_t newcap = st.heap_cap ? st.heap_cap * 2 : 16;
    while (newcap < need) newcap <<= 1;
    st.heap = (HeapNode*)realloc(st.heap, newcap * sizeof(HeapNode));
    st.heap_cap = newcap;
}

/* Ensure that st.wait has an entry for index idx */
static void st_ensure_wait(size_t idx)
{
    if (idx < st.wait_cap) return;
    size_t newcap = st.wait_cap ? st.wait_cap * 2 : 4;
    while (newcap <= idx) newcap <<= 1;
    st.wait = (IdxArr*)realloc(st.wait, newcap * sizeof(IdxArr));
    for (size_t k = st.wait_cap; k < newcap; ++k) {
        st.wait[k].d   = NULL;
        st.wait[k].len = 0;
        st.wait[k].cap = 0;
    }
    st.wait_cap = newcap;
}

/* Push index i onto st.wait[j] */
static void st_wait_push(idx_t j, idx_t i)
{
    st_ensure_wait(j);
    IdxArr *arr = &st.wait[j];
    if (arr->len == arr->cap) {
        size_t newcap = arr->cap ? arr->cap * 2 : 4;
        arr->d = (idx_t*)realloc(arr->d, newcap * sizeof(idx_t));
        arr->cap = newcap;
    }
    arr->d[arr->len++] = i;
}

/* Heap operations ------------------------------------------------- */

/* Push a node onto the min‑heap */
static void heap_push(HeapNode node)
{
    st_ensure_heap(st.heap_len + 1);
    size_t i = st.heap_len++;
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if (st.heap[p].val <= node.val) break;
        st.heap[i] = st.heap[p];
        i = p;
    }
    st.heap[i] = node;
}

/* Pop the smallest element from the heap */
static HeapNode heap_pop(void)
{
    HeapNode root = st.heap[0];
    size_t last = --st.heap_len;
    if (last) {
        HeapNode lastNode = st.heap[last];
        size_t i = 0;
        while (1) {
            size_t l = (i << 1) + 1;
            if (l >= st.heap_len) break;
            size_t r = l + 1;
            size_t smallest = (r < st.heap_len && st.heap[r].val < st.heap[l].val) ? r : l;
            if (st.heap[smallest].val >= lastNode.val) break;
            st.heap[i] = st.heap[smallest];
            i = smallest;
        }
        st.heap[i] = lastNode;
    }
    return root;
}

/* Compute the rule value for pair (i,j) */
static inline seq_t f_val(idx_t i, idx_t j)
{
    seq_t xi = st.seq[i];
    seq_t xj = st.seq[j];
    return ((xi + (seq_t)1) * (xj + (seq_t)1)) / (seq_t)2;
}

/* Initialise global state ------------------------------------------------ */

static void st_init(void)
{
    /* Avoid multiple initialisations */
    if (st.seq) return;

    /* First element 2 */
    st.seq_len = 1;
    st_ensure_seq(1);
    st.seq[0] = (seq_t)2;
    st.last_val = (seq_t)2;

    /* Initialise heap and push the first pair (0,0) */
    st.heap_cap = 16;
    st.heap = (HeapNode*)malloc(st.heap_cap * sizeof(HeapNode));
    st.heap_len = 0;
    heap_push((HeapNode){ .val = f_val(0,0), .i = 0, .j = 0 });

    /* Initialise waiting array */
    st.wait_cap = 4;
    st.wait = (IdxArr*)malloc(st.wait_cap * sizeof(IdxArr));
    for (size_t k = 0; k < st.wait_cap; ++k) {
        st.wait[k].d   = NULL;
        st.wait[k].len = 0;
        st.wait[k].cap = 0;
    }
}

/* Main function ---------------------------------------------------------- */

seq_t a(idx_t n)
{
    st_init();
    if (n == (idx_t)1) return st.seq[0];

    /* Generate until we have at least n elements */
    while (st.seq_len < (size_t)n) {
        HeapNode cur = heap_pop();
        seq_t val = cur.val;

        /* Skip duplicate values */
        if (val == st.last_val) {
            idx_t new_j = cur.j + 1;
            if (new_j < st.seq_len) {
                heap_push((HeapNode){ .val = f_val(cur.i, new_j),
                                      .i   = cur.i, .j = new_j });
            } else {
                st_wait_push(new_j, cur.i);
            }
            continue;
        }

        /* New distinct value: extend the sequence */
        st.seq_len++;
        st_ensure_seq(st.seq_len);
        st.seq[st.seq_len-1] = val;
        st.last_val = val;
        idx_t new_idx = st.seq_len - 1;

        /* Pair (new_idx,new_idx) self */
        heap_push((HeapNode){ .val = f_val(new_idx, new_idx),
                              .i   = new_idx, .j = new_idx });

        /* Process any pairs waiting for this second index */
        st_ensure_wait(new_idx);
        IdxArr *arr = &st.wait[new_idx];
        for (size_t t = 0; t < arr->len; ++t) {
            idx_t i = arr->d[t];
            heap_push((HeapNode){ .val = f_val(i, new_idx),
                                  .i   = i, .j = new_idx });
        }
        arr->len = 0;  /* clear for reuse */

        /* Advance the originally popped pair */
        idx_t new_j = cur.j + 1;
        if (new_j < st.seq_len) {
            heap_push((HeapNode){ .val = f_val(cur.i, new_j),
                                  .i   = cur.i, .j = new_j });
        } else {
            st_wait_push(new_j, cur.i);
        }
    }

    return st.seq[n-1];
}
